package de.hhu.stups.xml2b;

import de.hhu.stups.xml2b.readXml.XMLElement;
import de.hhu.stups.xml2b.readXml.XMLReader;
import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

import java.io.File;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;

/**
 * @author generated by Claude
 */
public class XMLReaderTest {

	@TempDir
	Path tmp;

	private File write(String name, String content) throws IOException {
		Path file = tmp.resolve(name);
		Files.writeString(file, content);
		return file.toFile();
	}

	private static XMLElement byName(List<XMLElement> elements, String name) {
		return elements.stream().filter(e -> e.elementType().getLocalPart().equals(name)).findFirst().orElseThrow();
	}

	@Test
	void testEntityReferenceKeepsText() throws Exception {
		File xml = write("entity.xml", "<?xml version=\"1.0\"?>\n<root>\n  <a>Tom &amp; Jerry</a>\n</root>\n");
		XMLReader reader = new XMLReader();
		List<XMLElement> elements = reader.readXML(xml, null);
		Assertions.assertTrue(reader.getErrors().isEmpty());
		Assertions.assertEquals("Tom & Jerry", byName(elements, "a").content());
		Assertions.assertEquals("", byName(elements, "root").content());
	}

	@Test
	void testLongTextIsNotModified() throws Exception {
		String text = "word ".repeat(4000).trim();
		File xml = write("long.xml", "<?xml version=\"1.0\"?>\n<r>" + text + "</r>\n");
		List<XMLElement> elements = new XMLReader().readXML(xml, null);
		Assertions.assertEquals(text, elements.get(0).content());
	}

	@Test
	void testIdsAndPathsInDocumentOrder() throws Exception {
		File xml = write("tree.xml", "<a>\n  <b>\n    <c/>\n  </b>\n  <d/>\n</a>\n");
		List<XMLElement> elements = new XMLReader().readXML(xml, null);
		Assertions.assertEquals(4, elements.size());
		for (int i = 0; i < elements.size(); i++) {
			Assertions.assertEquals(i + 1, elements.get(i).recId());
		}
		XMLElement a = byName(elements, "a"), b = byName(elements, "b"), c = byName(elements, "c"), d = byName(elements, "d");
		Assertions.assertEquals(List.of(0), a.pIds());
		Assertions.assertEquals(List.of(1), b.pIds());
		Assertions.assertEquals(List.of(1, 2), c.pIds());
		Assertions.assertEquals(List.of(1), d.pIds());
		Assertions.assertEquals(4, a.maxCId());
		Assertions.assertEquals(3, b.maxCId());
		Assertions.assertEquals(3, c.maxCId());
		Assertions.assertEquals(4, d.maxCId());
		Assertions.assertEquals(2, c.pNames().size());
		Assertions.assertEquals("a", c.pNames().get(0).getLocalPart());
		Assertions.assertEquals("b", c.pNames().get(1).getLocalPart());
	}

	@Test
	void testMalformedXmlIsReported() throws Exception {
		File xml = write("broken.xml", "<a><b></a>");
		XMLReader reader = new XMLReader();
		reader.readXML(xml, null);
		Assertions.assertFalse(reader.getErrors().isEmpty());
	}

	@Test
	void testMissingFileIsReported() {
		XMLReader reader = new XMLReader();
		reader.readXML(tmp.resolve("does-not-exist.xml").toFile(), null);
		Assertions.assertEquals(1, reader.getErrors().size());
	}

	@Test
	void testInvalidSchemaIsReported() throws Exception {
		File xml = write("ok.xml", "<a/>");
		File xsd = write("broken.xsd", "<xs:schema xmlns:xs=\"http://www.w3.org/2001/XMLSchema\"><xs:element</xs:schema>");
		XMLReader reader = new XMLReader();
		reader.readXML(xml, xsd);
		Assertions.assertFalse(reader.getErrors().isEmpty());
	}
}
